import { readFileSync } from 'node:fs'
import { createElement } from 'react'
import { renderToStaticMarkup } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import ZoneMonitoring from './ZoneMonitoring.jsx'

// These points and baselines were generated by app/qc.py. Restrict each render
// to one real fixture point so provisional and formal verdicts cannot mix.
const demo = JSON.parse(readFileSync(new URL('../mock/demo.responses.json', import.meta.url), 'utf8'))['A,B']
function renderStatus(status) {
  const source = structuredClone(demo)
  const point = source.daily_points.find((p) => p.zone === 'A' && p.status === status)
  const baseline = source.zone_baselines.find((b) => b.zone === 'A')
  expect(baseline.status).toBe('ready')
  expect(baseline.reviewed).toBe(true)
  const count = baseline.n + point.n
  const coverage = { total_rows: count, usable_rows: count, excluded_rows: 0, usable_fraction: 1 }
  const result = {
    ...source,
    meta: { ...source.meta, reviewed_zones: ['A'] },
    quality: { overall: coverage, selected_priority: coverage, unassigned_priority_rows: 0, reasons: [] },
    zone_baselines: [baseline], daily_points: [point],
    signals: status === 'high' ? [point] : [], excluded_records: [],
    late_incidents: source.late_incidents.filter((r) => r.zone === 'A' && (r.phase === 'baseline' || r.date === point.date)),
  }
  return renderToStaticMarkup(createElement(ZoneMonitoring, {
    res: result, busy: false, source: 'Synthetic render fixture',
    onToggleReviewed() {}, onViewIncidents() {}, onBack() {},
  }))
}

describe('reviewed baseline does not turn a partial day into a verdict', () => {
  it('shows no verdicts for reviewed partial-only monitoring', () => {
    const html = renderStatus('provisional_current_day')
    expect(html).toContain('<h1>No completed-day verdicts yet</h1>')
    expect(html).toContain('<span class="ztag na">no verdicts</span>')
    expect(html).toContain('Provisional (today)')
    expect(html).not.toContain('<span class="ztag ok">')
    expect(html).not.toContain('<h1>No formal control-chart signals</h1>')
  })

  it('distinguishes a closed no-signal verdict from missing verdicts', () => {
    const html = renderStatus('no_signal')
    expect(html).toContain('<h1>No formal control-chart signals</h1>')
    expect(html).toContain('<span class="ztag ok">no formal signals</span>')
    expect(html).not.toContain('<span class="ztag na">no verdicts</span>')
    expect(html).not.toContain('<h1>No completed-day verdicts yet</h1>')
  })

  it('still renders a formal high signal with its zone headline and card', () => {
    const html = renderStatus('high')
    expect(html).toContain('<h1>A is running late more often than its own baseline</h1>')
    expect(html).toContain('<span class="ztag hi">1 high day</span>')
    expect(html).toContain('data-signal="true"')
    expect(html).toContain('High late rate')
    expect(html).not.toContain('<h1>No completed-day verdicts yet</h1>')
  })
})

describe('persistent chart selection and observed-date wording', () => {
  const renderSelection = (result, selection) => renderToStaticMarkup(createElement(ZoneMonitoring, {
    res: result, busy: false, source: 'Synthetic render fixture', selection,
    onSelectionChange() {}, onToggleReviewed() {}, onViewIncidents() {}, onBack() {},
  }))

  it('renders the controlled zone and date instead of defaulting to the highest day', () => {
    const selected = demo.daily_points.find((p) => p.zone === 'B')
    const html = renderSelection(demo, { zone: 'B', date: selected.date })
    expect(html).toContain('B · daily share of late arrivals (p chart)')
    expect(html).toContain(`class="cell ${selected.status === 'high' ? 'hi' : selected.status === 'low' ? 'lo' : selected.status === 'no_signal' ? 'ok' : 'na'} sel"`)
    expect(html).toContain('data-focus-target="chart" tabindex="-1"')
    expect(html).toContain('data-focus-target="incident-link"')
  })

  it('keeps an explicitly selected missing date with an honest empty message', () => {
    const html = renderSelection(demo, { zone: 'B', date: '2026-08-01' })
    expect(html).toContain('B · Aug 1 · selected date')
    expect(html).toContain('No monitoring observation for this zone on 2026-08-01')
    expect(html).not.toContain('· slowest late responses</h2>')
  })

  it('labels sparse observations and does not bridge them in the mini chart', () => {
    const dates = ['2026-08-21', '2026-08-24', '2026-08-28', '2026-09-01', '2026-09-05', '2026-09-10', '2026-09-18']
    const source = structuredClone(demo)
    source.zone_baselines = source.zone_baselines.filter((b) => b.zone === 'A')
    const template = source.daily_points.find((p) => p.zone === 'A')
    source.daily_points = dates.map((date) => ({ ...template, date }))
    source.signals = []
    const html = renderSelection(source, { zone: 'A', date: dates[0] })
    expect(html).toContain('7 observed monitoring dates · Aug 21–Sep 18 (29 calendar days)')
    expect(html).toContain('1 cell = 1 observed date; gaps omitted')
    expect(html.match(/data-spark-segment="point"/g)).toHaveLength(7)
    expect(html).not.toContain('data-spark-segment="line"')
  })
})
